package http

import (
	"net/url"
	"path"

	"github.com/GopeedLab/gopeed/internal/fetcher"
	"github.com/GopeedLab/gopeed/pkg/base"
	fhttp "github.com/GopeedLab/gopeed/pkg/protocol/http"
)

// ============================================================================
// Fetcher Data (for Store/Restore)
// ============================================================================

type fetcherData struct {
	Connections           []*connection
	RedirectURL           string // Saved redirect URL for resume
	IfRange               string // Strong ETag or Last-Modified validator for safe resume
	RangeReprobeEligible  bool   // Origin advertised Range before falling back to sequential mode
	RangeValidatorPinned  bool   // Recovered Range mode must keep the same If-Range validator
	SequentialSizeUnknown bool   // Interrupted chunked sequential streams restart from byte zero
	SizeKnown             *bool  // Nil for legacy snapshots; false means Size is only a display estimate
	Range                 *bool  // Authoritative Range mode; nil for records saved by older versions
	ResourceSize          *int64 // Display size from the same snapshot; authority is recorded by SizeKnown
	FileSize              *int64 // Single-file size from the same snapshot; nil for older records
}

// ============================================================================
// Fetcher Manager
// ============================================================================

type FetcherManager struct {
}

func (fm *FetcherManager) Name() string {
	return "http"
}

func (fm *FetcherManager) Filters() []*fetcher.SchemeFilter {
	return []*fetcher.SchemeFilter{
		{
			Type:    fetcher.FilterTypeUrl,
			Pattern: "HTTP",
		},
		{
			Type:    fetcher.FilterTypeUrl,
			Pattern: "HTTPS",
		},
	}
}

func (fm *FetcherManager) Build() fetcher.Fetcher {
	return &Fetcher{}
}

func (fm *FetcherManager) ParseName(u string) string {
	var name string
	url, err := url.Parse(u)
	if err != nil {
		return ""
	}
	name = path.Base(url.Path)
	if name == "" || name == "/" || name == "." {
		name = url.Hostname()
	}
	return name
}

func (fm *FetcherManager) AutoRename() bool {
	return true
}

func (fm *FetcherManager) DefaultConfig() any {
	return &config{
		UserAgent:   DefaultUserAgent,
		Connections: 16,
	}
}

func (fm *FetcherManager) Store(f fetcher.Fetcher) (data any, err error) {
	_f := f.(*Fetcher)
	_f.redirectLock.Lock()
	redirectURL := _f.redirectURL
	_f.redirectLock.Unlock()

	// Build an immutable snapshot while holding the same lock used by download
	// workers to update Range mode and connection progress. The storage layer
	// marshals this value after Store returns, so returning live pointers would
	// otherwise race with the active download and could persist a mixed state.
	_f.connMu.Lock()
	connections := snapshotConnectionsLocked(_f.connections)
	ifRange := _f.ifRange
	rangeReprobeEligible := _f.rangeReprobeEligible
	rangeValidatorPinned := _f.rangeValidatorPinned
	sequentialSizeUnknown := _f.sequentialSizeUnknown
	sizeKnown := _f.hasKnownSize()
	var rangeMode *bool
	var resourceSize *int64
	var fileSize *int64
	if _f.meta != nil && _f.meta.Res != nil {
		value := _f.meta.Res.Range
		rangeMode = &value
		size := _f.meta.Res.Size
		resourceSize = &size
		if len(_f.meta.Res.Files) > 0 && _f.meta.Res.Files[0] != nil {
			size := _f.meta.Res.Files[0].Size
			fileSize = &size
		}
	}
	_f.connMu.Unlock()

	return &fetcherData{
		Connections:           connections,
		RedirectURL:           redirectURL,
		IfRange:               ifRange,
		RangeReprobeEligible:  rangeReprobeEligible,
		RangeValidatorPinned:  rangeValidatorPinned,
		SequentialSizeUnknown: sequentialSizeUnknown,
		SizeKnown:             &sizeKnown,
		Range:                 rangeMode,
		ResourceSize:          resourceSize,
		FileSize:              fileSize,
	}, nil
}

// snapshotConnectionsLocked copies only the serialized connection state and
// deep-copies chunks. The caller must hold the fetcher's connMu.
func snapshotConnectionsLocked(connections []*connection) []*connection {
	snapshot := make([]*connection, len(connections))
	for i, conn := range connections {
		if conn == nil {
			continue
		}
		copyConn := &connection{
			ID:         conn.ID,
			Role:       conn.Role,
			State:      conn.State,
			Downloaded: conn.Downloaded,
			Completed:  conn.Completed,
		}
		if conn.Chunk != nil {
			copyChunk := *conn.Chunk
			if conn.Chunk.End != nil {
				end := *conn.Chunk.End
				copyChunk.End = &end
			}
			copyConn.Chunk = &copyChunk
		}
		snapshot[i] = copyConn
	}
	return snapshot
}

func (fm *FetcherManager) Restore() (v any, f func(meta *fetcher.FetcherMeta, v any) fetcher.Fetcher) {
	return &fetcherData{}, func(meta *fetcher.FetcherMeta, v any) fetcher.Fetcher {
		fd := v.(*fetcherData)
		fb := &FetcherManager{}
		fetcher := fb.Build().(*Fetcher)
		fetcher.meta = meta
		base.ParseReqExtra[fhttp.ReqExtra](fetcher.meta.Req)
		base.ParseOptExtra[fhttp.OptsExtra](fetcher.meta.Opts)
		if len(fd.Connections) > 0 {
			fetcher.connections = fd.Connections
		}
		// Restore redirect URL for resume
		if fd.RedirectURL != "" {
			fetcher.redirectURL = fd.RedirectURL
		}
		fetcher.ifRange = fd.IfRange
		fetcher.rangeReprobeEligible = fd.RangeReprobeEligible
		fetcher.rangeValidatorPinned = fd.RangeValidatorPinned
		fetcher.sequentialSizeUnknown = fd.SequentialSizeUnknown
		if fd.SizeKnown != nil {
			known := *fd.SizeKnown
			fetcher.sizeKnown = &known
		}
		if fd.Range != nil && fetcher.meta.Res != nil {
			// Recovery-critical resource fields live in the same persisted snapshot
			// as Connections, making them authoritative over task metadata that may
			// have been saved just before or after this record.
			fetcher.meta.Res.Range = *fd.Range
		}
		if fd.ResourceSize != nil && fetcher.meta.Res != nil {
			fetcher.meta.Res.Size = *fd.ResourceSize
		}
		if fd.FileSize != nil && fetcher.meta.Res != nil && len(fetcher.meta.Res.Files) > 0 && fetcher.meta.Res.Files[0] != nil {
			fetcher.meta.Res.Files[0].Size = *fd.FileSize
		}
		return fetcher
	}
}

func (fm *FetcherManager) Close() error {
	return nil
}

package http

import (
	"encoding/hex"
	"fmt"
	"strings"
)

type ReqExtra struct {
	Method string            `json:"method"`
	Header map[string]string `json:"header"`
	Body   string            `json:"body"`
}

// ChecksumOption specifies an expected checksum to verify against
// the completed download. Only supported for HTTP downloads.
type ChecksumOption struct {
	Algorithm string `json:"algorithm"` // "md5" | "sha1" | "sha256"
	Expected  string `json:"expected"`  // hex-encoded expected hash
}

// IsEmpty returns true when chk is nil, or when both Algorithm and Expected
// are blank after trimming whitespace.
func (chk *ChecksumOption) IsEmpty() bool {
	if chk == nil {
		return true
	}
	return strings.TrimSpace(chk.Algorithm) == "" && strings.TrimSpace(chk.Expected) == ""
}

// NormalizedAlgorithm returns the canonical lower-cased algorithm ("md5", "sha1", "sha256")
// and true if recognized, or ("", false) if unsupported.
func (chk *ChecksumOption) NormalizedAlgorithm() (string, bool) {
	if chk == nil {
		return "", false
	}
	switch strings.ToLower(strings.TrimSpace(chk.Algorithm)) {
	case "md5":
		return "md5", true
	case "sha1", "sha-1":
		return "sha1", true
	case "sha256", "sha-256":
		return "sha256", true
	default:
		return "", false
	}
}

// Validate checks whether the checksum option is valid.
// Empty options return nil (no verification).
func (chk *ChecksumOption) Validate() error {
	if chk.IsEmpty() {
		return nil
	}
	algo, ok := chk.NormalizedAlgorithm()
	if !ok {
		return fmt.Errorf("unsupported checksum algorithm: %s", chk.Algorithm)
	}
	expected := strings.TrimSpace(chk.Expected)
	if expected == "" {
		return fmt.Errorf("checksum expected hash is required when algorithm is set")
	}
	var expectedLen int
	switch algo {
	case "md5":
		expectedLen = 32
	case "sha1":
		expectedLen = 40
	case "sha256":
		expectedLen = 64
	}
	if len(expected) != expectedLen {
		return fmt.Errorf("invalid checksum hash length for %s: expected %d characters, got %d", algo, expectedLen, len(expected))
	}
	if _, err := hex.DecodeString(expected); err != nil {
		return fmt.Errorf("invalid checksum hash for %s: expected valid hexadecimal string", algo)
	}
	return nil
}

type OptsExtra struct {
	Connections int `json:"connections"`
	// AutoTorrent when task download complete, and it is a .torrent file, it will be auto create a new task for the torrent file
	// nil means use global config, true/false means explicit setting
	AutoTorrent *bool `json:"autoTorrent"`
	// DeleteTorrentAfterDownload when true, deletes the .torrent file after creating BT task
	// nil means use global config, true/false means explicit setting
	DeleteTorrentAfterDownload *bool `json:"deleteTorrentAfterDownload"`
	// AutoExtract when task download complete, and it is an archive file, it will be auto extracted
	// nil means use global config, true/false means explicit setting
	AutoExtract *bool `json:"autoExtract"`
	// ArchivePassword is the password for extracting password-protected archives
	ArchivePassword string `json:"archivePassword"`
	// DeleteAfterExtract when true, deletes the archive file after successful extraction
	DeleteAfterExtract bool `json:"deleteAfterExtract"`
	// Checksum verifies the completed file against an expected hash after download
	Checksum *ChecksumOption `json:"checksum,omitempty"`
}

// Stats for download
type Stats struct {
	Connections []*StatsConnection `json:"connections"`
}

type StatsConnection struct {
	Downloaded int64 `json:"downloaded"`
	// Total is the resource size divided by the current number of connections,
	// rounded up to a whole byte. Every connection in one snapshot uses the same
	// denominator so clients can compare their downloaded contributions. It is
	// zero when the resource size is unknown.
	Total      int64 `json:"total"`
	Completed  bool  `json:"completed"`
	Failed     bool  `json:"failed"`
	RetryTimes int   `json:"retryTimes"`
}

