316		return startTestServer(func(sl *shutdownListener) http.Handler {
317			mux := http.NewServeMux()
318			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
319				// First full download request succeeds, subsequent requests fail
320				if accessed.Swap(true) {
321					writer.WriteHeader(404)
322					return
323				}
