1	package http
2	
3	import (
4		"net/url"
5		"path"
6	
7		"github.com/GopeedLab/gopeed/internal/fetcher"
8		"github.com/GopeedLab/gopeed/pkg/base"
9		fhttp "github.com/GopeedLab/gopeed/pkg/protocol/http"
10	)
11	
12	// ============================================================================
13	// Fetcher Data (for Store/Restore)
14	// ============================================================================
15	
16	type fetcherData struct {
17		Connections           []*connection
18		RedirectURL           string // Saved redirect URL for resume
19		IfRange               string // Strong ETag or Last-Modified validator for safe resume
20		RangeReprobeEligible  bool   // Origin advertised Range before falling back to sequential mode
21		RangeValidatorPinned  bool   // Recovered Range mode must keep the same If-Range validator
22		SequentialSizeUnknown bool   // Interrupted chunked sequential streams restart from byte zero
23		SizeKnown             *bool  // Nil for legacy snapshots; false means Size is only a display estimate
24		Range                 *bool  // Authoritative Range mode; nil for records saved by older versions
25		ResourceSize          *int64 // Display size from the same snapshot; authority is recorded by SizeKnown
26		FileSize              *int64 // Single-file size from the same snapshot; nil for older records
27	}
28	
29	// ============================================================================
30	// Fetcher Manager
31	// ============================================================================
32	
33	type FetcherManager struct {
34	}
35	
36	func (fm *FetcherManager) Name() string {
37		return "http"
38	}
39	
40	func (fm *FetcherManager) Filters() []*fetcher.SchemeFilter {
41		return []*fetcher.SchemeFilter{
42			{
43				Type:    fetcher.FilterTypeUrl,
44				Pattern: "HTTP",
45			},
46			{
47				Type:    fetcher.FilterTypeUrl,
48				Pattern: "HTTPS",
49			},
50		}
51	}
52	
53	func (fm *FetcherManager) Build() fetcher.Fetcher {
54		return &Fetcher{}
55	}
56	
57	func (fm *FetcherManager) ParseName(u string) string {
58		var name string
59		url, err := url.Parse(u)
60		if err != nil {
61			return ""
62		}
63		name = path.Base(url.Path)
64		if name == "" || name == "/" || name == "." {
65			name = url.Hostname()
66		}
67		return name
68	}
69	
70	func (fm *FetcherManager) AutoRename() bool {
71		return true
72	}
73	
74	func (fm *FetcherManager) DefaultConfig() any {
75		return &config{
76			UserAgent:   DefaultUserAgent,
77			Connections: 16,
78		}
79	}
80	
81	func (fm *FetcherManager) Store(f fetcher.Fetcher) (data any, err error) {
82		_f := f.(*Fetcher)
83		_f.redirectLock.Lock()
84		redirectURL := _f.redirectURL
85		_f.redirectLock.Unlock()
86	
87		// Build an immutable snapshot while holding the same lock used by download
88		// workers to update Range mode and connection progress. The storage layer
89		// marshals this value after Store returns, so returning live pointers would
90		// otherwise race with the active download and could persist a mixed state.
91		_f.connMu.Lock()
92		connections := snapshotConnectionsLocked(_f.connections)
93		ifRange := _f.ifRange
94		rangeReprobeEligible := _f.rangeReprobeEligible
95		rangeValidatorPinned := _f.rangeValidatorPinned
96		sequentialSizeUnknown := _f.sequentialSizeUnknown
97		sizeKnown := _f.hasKnownSize()
98		var rangeMode *bool
99		var resourceSize *int64
100		var fileSize *int64
101		if _f.meta != nil && _f.meta.Res != nil {
102			value := _f.meta.Res.Range
103			rangeMode = &value
104			size := _f.meta.Res.Size
105			resourceSize = &size
106			if len(_f.meta.Res.Files) > 0 && _f.meta.Res.Files[0] != nil {
107				size := _f.meta.Res.Files[0].Size
108				fileSize = &size
109			}
110		}
111		_f.connMu.Unlock()
112	
113		return &fetcherData{
114			Connections:           connections,
115			RedirectURL:           redirectURL,
116			IfRange:               ifRange,
117			RangeReprobeEligible:  rangeReprobeEligible,
118			RangeValidatorPinned:  rangeValidatorPinned,
119			SequentialSizeUnknown: sequentialSizeUnknown,
120			SizeKnown:             &sizeKnown,
121			Range:                 rangeMode,
122			ResourceSize:          resourceSize,
123			FileSize:              fileSize,
124		}, nil
125	}
126	
127	// snapshotConnectionsLocked copies only the serialized connection state and
128	// deep-copies chunks. The caller must hold the fetcher's connMu.
129	func snapshotConnectionsLocked(connections []*connection) []*connection {
130		snapshot := make([]*connection, len(connections))
131		for i, conn := range connections {
132			if conn == nil {
133				continue
134			}
135			copyConn := &connection{
136				ID:         conn.ID,
137				Role:       conn.Role,
138				State:      conn.State,
139				Downloaded: conn.Downloaded,
140				Completed:  conn.Completed,
141			}
142			if conn.Chunk != nil {
143				copyChunk := *conn.Chunk
144				if conn.Chunk.End != nil {
145					end := *conn.Chunk.End
146					copyChunk.End = &end
147				}
148				copyConn.Chunk = &copyChunk
149			}
150			snapshot[i] = copyConn
151		}
152		return snapshot
153	}
154	
155	func (fm *FetcherManager) Restore() (v any, f func(meta *fetcher.FetcherMeta, v any) fetcher.Fetcher) {
156		return &fetcherData{}, func(meta *fetcher.FetcherMeta, v any) fetcher.Fetcher {
157			fd := v.(*fetcherData)
158			fb := &FetcherManager{}
159			fetcher := fb.Build().(*Fetcher)
160			fetcher.meta = meta
161			base.ParseReqExtra[fhttp.ReqExtra](fetcher.meta.Req)
162			base.ParseOptExtra[fhttp.OptsExtra](fetcher.meta.Opts)
163			if len(fd.Connections) > 0 {
164				fetcher.connections = fd.Connections
165			}
166			// Restore redirect URL for resume
167			if fd.RedirectURL != "" {
168				fetcher.redirectURL = fd.RedirectURL
169			}
170			fetcher.ifRange = fd.IfRange
171			fetcher.rangeReprobeEligible = fd.RangeReprobeEligible
172			fetcher.rangeValidatorPinned = fd.RangeValidatorPinned
173			fetcher.sequentialSizeUnknown = fd.SequentialSizeUnknown
174			if fd.SizeKnown != nil {
175				known := *fd.SizeKnown
176				fetcher.sizeKnown = &known
177			}
178			if fd.Range != nil && fetcher.meta.Res != nil {
179				// Recovery-critical resource fields live in the same persisted snapshot
180				// as Connections, making them authoritative over task metadata that may
181				// have been saved just before or after this record.
182				fetcher.meta.Res.Range = *fd.Range
183			}
184			if fd.ResourceSize != nil && fetcher.meta.Res != nil {
185				fetcher.meta.Res.Size = *fd.ResourceSize
186			}
187			if fd.FileSize != nil && fetcher.meta.Res != nil && len(fetcher.meta.Res.Files) > 0 && fetcher.meta.Res.Files[0] != nil {
188				fetcher.meta.Res.Files[0].Size = *fd.FileSize
189			}
190			return fetcher
191		}
192	}
193	
194	func (fm *FetcherManager) Close() error {
195		return nil
196	}
