31	// extractIfRangeValidator returns only validators that are strong enough for
32	// If-Range. Any entity-tag header blocks Last-Modified fallback: a weak or
33	// malformed ETag does not make the date validator strong.
34	func extractIfRangeValidator(header http.Header) string {
35		etag := strings.TrimSpace(header.Get(base.HttpHeaderETag))
36		if etag != "" {
37			if isStrongETag(etag) {
38				return etag
39			}
40			return ""
41		}
42	
43		lastModified := strings.TrimSpace(header.Get(base.HttpHeaderLastModified))
44		date := strings.TrimSpace(header.Get("Date"))
45		if lastModified == "" || date == "" {
46			return ""
47		}
48		modifiedAt, modifiedErr := http.ParseTime(lastModified)
49		responseAt, responseErr := http.ParseTime(date)
50		if modifiedErr != nil || responseErr != nil || responseAt.Sub(modifiedAt) < time.Second {
51			return ""
52		}
53		return lastModified
54	}
