56	func isStrongETag(value string) bool {
57		if len(value) < 2 || value[0] != '"' || value[len(value)-1] != '"' {
58			return false
59		}
60		for i := 1; i < len(value)-1; i++ {
61			b := value[i]
62			if b == 0x21 || (b >= 0x23 && b <= 0x7e) || b >= 0x80 {
63				continue
64			}
65			return false
66		}
67		return true
68	}
