299	// parseFilename extracts filename from Content-Disposition header
300	func parseFilename(contentDisposition string) string {
301		// Try RFC 5987 extended notation first (filename*=)
302		if filename := parseFilenameExtended(contentDisposition); filename != "" {
303			return filename
304		}
305	
306		// Try standard MIME parsing
307		_, params, err := mime.ParseMediaType(contentDisposition)
308		if err == nil {
309			if filename := params["filename"]; filename != "" {
310				return decodeFilenameParam(filename)
311			}
312		}
313	
314		// Fallback to manual parsing
315		return parseFilenameFallback(contentDisposition)
316	}
