340	// parseFilenameExtended handles RFC 5987 extended notation (filename*=)
341	// Format: filename*=charset'language'value (e.g., UTF-8”%E6%B5%8B%E8%AF%95.zip)
342	func parseFilenameExtended(cd string) string {
343		lower := strings.ToLower(cd)
344		idx := strings.Index(lower, "filename*=")
345		if idx == -1 {
346			return ""
347		}
348	
349		value := cd[idx+len("filename*="):]
350	
351		// Find the end of the value using proper quote handling
352		endIdx := findParamValueEnd(value)
353		if endIdx != -1 {
354			value = value[:endIdx]
355		}
356		value = strings.TrimSpace(value)
357	
358		// Try charset''encoded format (e.g., UTF-8''%E4%B8%AD%E6%96%87.txt)
359		parts := strings.SplitN(value, "''", 2)
360		if len(parts) == 2 {
361			// Use PathUnescape to handle %2B correctly (should decode to +, not space)
362			decoded, err := url.PathUnescape(parts[1])
363			if err == nil {
364				return decoded
365			}
366		}
367	
368		// Try charset'language'encoded format
369		parts = strings.SplitN(value, "'", 3)
370		if len(parts) >= 3 {
371			// Use PathUnescape to handle %2B correctly (should decode to +, not space)
372			decoded, err := url.PathUnescape(parts[2])
373			if err == nil {
374				return decoded
375			}
376		}
377	
378		return ""
379	}
