16	func TestResolveResponseSize(t *testing.T) {
17		for _, tc := range []struct {
18			name                 string
19			status               int
20			length, contentRange string
21			size                 int64
22			invalid              bool
23		}{
24			{"full", 200, "801571015", "", 801571015, false},
25			{"partial_prefix", 206, "472321339", "bytes 0-472321338/801571015", 801571015, false},
26			{"partial_nonzero", 206, "100000", "bytes 100000-199999/801571015", 801571015, false},
27			{"second_report", 206, "335134409", "bytes 0-335134408/552140234", 552140234, false},
28			{"length_mismatch", 206, "10", "bytes 0-19/100", 0, true},
29			{"unknown_total", 206, "472321339", "bytes 0-472321338/*", 0, true},
30			{"missing_range", 206, "10", "", 0, true},
31			{"malformed_range", 206, "10", "bytes invalid", 0, true},
32			{"invalid_bounds", 206, "10", "bytes 20-10/100", 0, true},
33			{"invalid_total", 206, "10", "bytes 0-9/9", 0, true},
34			{"overflow", 206, "10", "bytes 0-9/9223372036854775808", 0, true},
35			{"chunked_partial", 206, "", "bytes 0-9/100", 100, false},
36			{"unknown_full", 200, "", "", 0, false},
37		} {
38			t.Run(tc.name, func(t *testing.T) {
39				server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
40					if tc.length != "" {
41						w.Header().Set("Content-Length", tc.length)
42					}
43					if tc.contentRange != "" {
44						w.Header().Set("Content-Range", tc.contentRange)
45					}
46					w.WriteHeader(tc.status)
47					w.(http.Flusher).Flush()
48				}))
49				defer server.Close()
50				f := buildFetcher()
51				defer f.Close()
52				f.Meta().Opts = &base.Options{Path: t.TempDir()}
53				err := f.Resolve(&base.Request{URL: server.URL + "/file"})
54				if tc.invalid {
55					if !errors.Is(err, errInvalidRangeResponse) {
56						t.Fatalf("Resolve error = %v, want invalid range", err)
57					}
58					if f.meta.Res != nil || f.resolveResp != nil || f.getState() != stateError {
59						t.Fatal("invalid response was retained or published")
60					}
61					return
62				}
63				if err != nil {
